// The native shell: SQLite for the Rust core, which asks for every statement it needs (a Crux-style effect), through
// the UniFFI bindings in CoreBindings.swift (crates/gp-core-ffi, generated by its bindings.sh).
import Foundation
import SQLite3

public struct SQLError: Error, CustomStringConvertible { public let description: String }

private let SQLITE_TRANSIENT = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

public final class Database {
    let db: OpaquePointer

    public init(path: String) throws {
        var p: OpaquePointer?
        guard sqlite3_open(path, &p) == SQLITE_OK, let p else { throw SQLError(description: "cannot open \(path)") }
        db = p
    }
    deinit { sqlite3_close(db) }

    private var message: String { String(cString: sqlite3_errmsg(db)) }

    /// Runs statements without rows; SQLite's refusal is thrown.
    public func exec(_ sql: String) throws {
        guard sqlite3_exec(db, sql, nil, nil, nil) == SQLITE_OK else { throw SQLError(description: message) }
    }

    /// Rows as SQLite holds them; a blob as null (the core reads no bytes).
    public func query(_ sql: String, _ params: [SqlValue] = []) throws -> [[SqlValue]] {
        var st: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &st, nil) == SQLITE_OK, let st else { throw SQLError(description: message) }
        defer { sqlite3_finalize(st) }
        for (i, v) in params.enumerated() {
            let at = Int32(i + 1)
            switch v {
            case .null: sqlite3_bind_null(st, at)
            case let .integer(n): sqlite3_bind_int64(st, at, n)
            case let .real(x): sqlite3_bind_double(st, at, x)
            case let .text(s): sqlite3_bind_text(st, at, s, -1, SQLITE_TRANSIENT)
            }
        }
        var rows: [[SqlValue]] = []
        while true {
            let rc = sqlite3_step(st)
            if rc == SQLITE_DONE { break }
            guard rc == SQLITE_ROW else { throw SQLError(description: message) }
            rows.append((0..<sqlite3_column_count(st)).map { c -> SqlValue in
                switch sqlite3_column_type(st, c) {
                case SQLITE_INTEGER: .integer(value: sqlite3_column_int64(st, c))
                case SQLITE_FLOAT: .real(value: sqlite3_column_double(st, c))
                case SQLITE_TEXT: .text(value: String(cString: sqlite3_column_text(st, c)))
                default: .null
                }
            })
        }
        return rows
    }
}

/// A refusal of the core's: its code (forbidden, not-found, invalid-args, limit, sql-error: …).
public struct Refusal: Error, CustomStringConvertible {
    public let code: String
    public var description: String { code }
}

/// The Rust core, run on a database. On the main actor: a call waits in the thread's own state between its steps, so
/// every call must come from one thread, one at a time.
@MainActor
public final class Core {
    public let db: Database
    /// The SQL calls of the last call, and its time in microseconds.
    public private(set) var lastSqlCalls = 0
    public private(set) var lastMicros = 0.0

    public init(db: Database) { self.db = db }

    /// Runs one call of the core to its end, answering each statement from the database: what it answered (a view's
    /// JSON text, none for a command), or its refusal. Runs in whatever transaction the caller holds.
    public func call(_ name: String, json args: String, caller: Caller?) -> Result<String?, Refusal> {
        let t = Date()
        lastSqlCalls = 0
        defer { lastMicros = Date().timeIntervalSince(t) * 1_000_000 }
        var step = start(name: name, args: args, caller: caller)
        while true {
            switch step {
            case let .done(json): return .success(json)
            case let .refused(code): return .failure(Refusal(code: code))
            case let .sql(sql, params):
                lastSqlCalls += 1
                do { step = resume(answer: .rows(rows: try db.query(sql, params))) }
                catch { step = resume(answer: .failed(message: "\(error)")) }
            }
        }
    }

    /// The same, the arguments given as a dictionary of JSON's values.
    public func call(_ name: String, _ args: [String: Any] = [:], caller: Caller?) -> Result<String?, Refusal> {
        call(name, json: Self.json(args), caller: caller)
    }

    /// Runs `body` in one transaction: committed when it returns, rolled back when it throws or the commit is refused
    /// (a foreign key a rebase left broken), as the web's SyncClient does.
    public func transaction<T>(_ body: () throws -> T) throws -> T {
        try db.exec("BEGIN")
        do {
            let result = try body()
            try db.exec("COMMIT")
            return result
        } catch {
            try? db.exec("ROLLBACK")
            throw error
        }
    }

    /// A command in a transaction of its own: what it answered, or its refusal, the transaction rolled back.
    public func command(_ name: String, json args: String, caller: Caller?) -> Result<String?, Refusal> {
        do { return .success(try transaction { try call(name, json: args, caller: caller).get() }) }
        catch let refusal as Refusal { return .failure(refusal) }
        catch { return .failure(Refusal(code: "sql-error: \(error)")) }
    }

    /// "ok", or the refusal's code. One transaction. `input` is {"name", "args", "ctx": {"userId", "role", "now"}},
    /// as the web's C interface took it (apps/mac's parity replays such records).
    public func mutate(_ input: [String: Any]) -> String {
        let ctx = input["ctx"] as? [String: Any]
        let caller = ctx.map { Caller(userId: $0["userId"] as? String ?? "", role: $0["role"] as? String ?? "", now: ($0["now"] as? NSNumber)?.doubleValue) }
        switch command(input["name"] as? String ?? "", json: Self.json(input["args"] ?? [:]), caller: caller) {
        case .success: return "ok"
        case let .failure(r): return r.code
        }
    }

    /// A view's JSON, decoded; nil when the core refuses or the answer does not decode.
    public func view<T: Decodable>(_ name: String, _ args: [String: Any] = [:], caller: Caller? = nil, as: T.Type) -> T? {
        guard case let .success(json?) = call(name, args, caller: caller) else { return nil }
        return try? JSONDecoder().decode(T.self, from: Data(json.utf8))
    }

    /// JSON's text of a value of JSONSerialization's kinds (NSNull, numbers, strings, arrays, dictionaries).
    public nonisolated static func json(_ value: Any) -> String {
        String(decoding: (try? JSONSerialization.data(withJSONObject: value, options: [.fragmentsAllowed])) ?? Data("null".utf8), as: UTF8.self)
    }
}
